export default async function install(app) {
 const inventory=app.getMount('content-inventory'),detail=app.getMount('dependency-explorer');
 const C={ink:'#172b4d',muted:'#64748b',line:'#dbe3ed',blue:'#1769aa',soft:'#eaf3fb',green:'#16805d',amber:'#a65d00'};
 const el=(tag,text,style={})=>{const n=document.createElement(tag);if(text!=null)n.textContent=text;Object.assign(n.style,style);return n;};
 const wrap={minWidth:'0',maxWidth:'100%',whiteSpace:'normal',wordBreak:'normal',overflowWrap:'anywhere',height:'auto',maxHeight:'none',overflow:'visible',boxSizing:'border-box'};
 const button=(text,fn,secondary=false)=>{const b=el('button',text,{border:`1px solid ${C.line}`,borderRadius:'8px',padding:'9px 12px',background:secondary?'white':C.blue,color:secondary?C.ink:'white',fontWeight:'700',cursor:'pointer',fontSize:'12px'});b.addEventListener('click',fn);return b;};
 const small=text=>el('div',text,{color:C.muted,fontSize:'11px',lineHeight:'1.55',...wrap});
 const section=(label,count)=>el('div',`${label.toUpperCase()}${count==null?'':` · ${count}`}`,{fontSize:'11px',fontWeight:'800',letterSpacing:'.06em',color:C.blue,margin:'16px 0 8px',...wrap});
 const state={portal:null,orgId:null,username:'',results:[],start:1,queryText:'',type:'',selected:null,dependencies:[],external:[],reverse:[],reverseMeta:null,tab:'dependencies',history:[],busy:false,cache:new Map(),reverseToken:0,total:0,hasMore:false,forwardNote:''};
 for(const root of [inventory,detail])Object.assign(root.style,{fontFamily:'Aptos, Segoe UI, sans-serif',color:C.ink,fontSize:'12px',...wrap});
 const search=el('input',null,{width:'100%',padding:'10px 11px',border:`1px solid ${C.line}`,borderRadius:'8px',marginBottom:'8px',boxSizing:'border-box'});search.type='search';search.placeholder='Buscar por título, etiqueta o palabra';search.setAttribute('aria-label','Buscar contenido');
 const type=el('select',null,{width:'100%',padding:'9px 10px',border:`1px solid ${C.line}`,borderRadius:'8px',marginBottom:'8px',boxSizing:'border-box'});type.setAttribute('aria-label','Filtrar por tipo de elemento');
 [['','Todos los tipos'],['Web Map','Web Map'],['Web Scene','Web Scene'],['Web Mapping Application','Aplicación web'],['Dashboard','Dashboard'],['StoryMap','StoryMap'],['Web Experience','Experience Builder'],['Feature Service','Feature Service'],['Map Service','Map Service'],['Image Service','Image Service'],['CSV','CSV'],['Microsoft Excel','Excel'],['Notebook','Notebook'],['Form','Form']].forEach(([v,t])=>{const o=el('option',t);o.value=v;type.append(o);});
 const status=small('Conectando…'),summary=el('div',null,{display:'flex',flexDirection:'column',gap:'5px',padding:'10px 0',...wrap}),countText=small('Preparando inventario'),selectedText=small('Sin selección');summary.append(countText,selectedText);
 const list=el('div'),searchBtn=button('Buscar',()=>runSearch(true)),loadMore=button('Cargar más resultados',()=>runSearch(false),true);loadMore.style.display='none';loadMore.style.width='100%';
 inventory.replaceChildren(small('Explora y selecciona un elemento para inspeccionar su contenido y relaciones.'),section('Búsqueda'),search,section('Tipo de elemento'),type,searchBtn,status,summary,list,loadMore);
 function cardBox(){return el('div',null,{border:`1px solid ${C.line}`,borderRadius:'9px',background:'white',padding:'11px',marginBottom:'8px',...wrap});}
 function itemCard(item,onClick,opts={}){
  const node=cardBox();node.setAttribute('role','button');node.tabIndex=0;node.setAttribute('aria-label',`${item.title}, ${item.type}`);node.style.cursor='pointer';node.style.borderLeft=`3px solid ${opts.tone||C.blue}`;if(state.selected?.id===item.id)node.style.background=C.soft;
  const title=el('div',item.title||'(Sin título)',{...wrap,width:'100%',fontSize:'13px',fontWeight:'750',lineHeight:'1.45'});title.dataset.itemTitle=item.id;
  const badge=el('span',item.type||'Desconocido',{display:'inline-block',marginTop:'6px',background:'#f2f5f8',color:C.muted,borderRadius:'5px',padding:'3px 6px',fontSize:'10px',...wrap});
  node.append(title,badge,small(`Propietario · ${item.owner||'No disponible'}`),el('div',`ID ${item.id}`,{color:'#8291a4',font:'9px monospace',marginTop:'5px',...wrap}));if(opts.badge)node.append(small(opts.badge));
  node.addEventListener('click',e=>{if(!e.target.closest('a'))onClick(item);});node.addEventListener('keydown',e=>{if(e.target===node&&(e.key==='Enter'||e.key===' ')){e.preventDefault();onClick(item);}});return node;
 }
 function renderInventory(){list.replaceChildren();for(const it of state.results)list.append(itemCard(it,selectItem));countText.textContent=`${state.results.length} de ${state.total} elementos`;selectedText.textContent=state.selected?`Activo · ${state.selected.title}`:'Sin selección';loadMore.style.display=state.hasMore?'block':'none';}
 function portalQuery(){const p=[];if(state.orgId)p.push(`orgid:${state.orgId}`);else if(state.username)p.push(`owner:${state.username}`);if(state.queryText)p.push(`(${state.queryText.replace(/[\\():]/g,' ').trim()})`);if(state.type)p.push(`type:"${state.type.replace(/"/g,'')}"`);return p.join(' AND ')||'*';}
 async function runSearch(reset){if(!state.portal||state.busy)return;if(reset){state.start=1;state.queryText=search.value.trim();state.type=type.value;state.results=[];}state.busy=true;status.textContent='Buscando en el portal…';searchBtn.disabled=true;try{const r=await state.portal.queryItems({query:portalQuery(),start:state.start,num:app.config.defaultPageSize,sortField:'modified',sortOrder:'desc'});const rows=(r.results||r.items||[]).map(x=>({id:x.id,title:x.title,type:x.type,owner:x.owner,modified:x.modified,access:x.access,url:x.url,itemPageUrl:x.itemPageUrl}));state.results=reset?rows:state.results.concat(rows);state.total=r.total||0;state.start+=rows.length;state.hasMore=state.start<=state.total&&rows.length>0;status.textContent=state.orgId?'ArcGIS Online · contenido accesible en la organización':'Sin organización identificada · mostrando contenido propio';renderInventory();}catch(e){status.textContent=`Error de consulta: ${e.message||e}`;}finally{state.busy=false;searchBtn.disabled=false;}}
 search.addEventListener('keydown',e=>{if(e.key==='Enter')runSearch(true);});type.addEventListener('change',()=>runSearch(true));
 function collectRefs(value){const ids=new Set(),urls=new Set(),idKeys=/^(itemid|portalitemid|webmapid|websceneid|storymapid|sourceitemid|mapitemid|item_id)$/i;function walk(v,key=''){if(v==null)return;if(typeof v==='string'){if(idKeys.test(key)&&/^[a-f0-9]{32}$/i.test(v))ids.add(v);for(const m of v.matchAll(/https?:\/\/[^\s\"'<>\\]+/gi)){const u=m[0].replace(/[),.;\]}]+$/,'');if(u.length<1800)urls.add(u);}const im=v.match(/(?:\/home\/item\.html\?id=|\/sharing\/rest\/content\/items\/)([a-f0-9]{32})/i);if(im)ids.add(im[1]);}else if(Array.isArray(v))v.forEach(x=>walk(x,key));else if(typeof v==='object')Object.keys(v).forEach(k=>walk(v[k],k));}walk(value);return{ids:[...ids],urls:[...urls]};}
 function relationKind(url){for(const [name,label]of [['FeatureServer','Feature Service'],['MapServer','Map Service'],['ImageServer','Image Service'],['VectorTileServer','Vector Tile Service'],['SceneServer','Scene Service']])if(url.toLowerCase().includes(name.toLowerCase()))return label;return'Servicio o recurso externo';}
 async function getItem(id){if(state.cache.has(id))return state.cache.get(id);const PortalItem=await app.import('esri/portal/PortalItem');const p=new PortalItem({id,portal:state.portal});let record;try{await p.load();record={meta:{id:p.id,title:p.title,type:p.type,owner:p.owner,url:p.url,access:p.access,modified:p.modified,itemPageUrl:p.itemPageUrl},portalItem:p};}catch(e){record={meta:{id,title:'Referencia no accesible',type:'No resuelto',owner:''},error:e.message||String(e)};}state.cache.set(id,record);return record;}
 function safeHref(it){return it.itemPageUrl||(it.id&&state.portal?.url?`${state.portal.url.replace(/\/$/,'')}/home/item.html?id=${encodeURIComponent(it.id)}`:null);}
 function linkTo(it,text){const url=safeHref(it);if(!url)return null;const a=el('a',text,{display:'inline-block',position:'static',color:C.blue,fontWeight:'700',fontSize:'11px',marginTop:'8px',...wrap});a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.addEventListener('click',e=>e.stopPropagation());return a;}
 async function resolveGraph(item){const record=await getItem(item.id);let data=null;const errors=[];try{data=await record.portalItem.fetchData('json');}catch(e){errors.push(`Datos del ítem no disponibles: ${e.message||e}`);}const refs=collectRefs(data||{});const resolved=await Promise.all(refs.ids.filter(id=>id!==item.id).slice(0,30).map(getItem));state.dependencies=resolved.map(r=>({...r.meta,unresolved:!!r.error}));state.external=refs.urls.filter(u=>!/\/home\/item\.html\?/i.test(u)&&!/\/sharing\/rest\/content\/items\//i.test(u)).map(url=>({url,type:relationKind(url),owner:new URL(url).hostname}));state.forwardNote=errors.length?errors.join(' · '):'Las referencias se extraen de los datos del ítem. Algunas aplicaciones guardan fuentes en recursos protegidos o formatos no analizables.';}
 async function selectItem(item,fromHistory=true){if(!item?.id||state.busy)return;if(state.selected&&fromHistory&&state.selected.id!==item.id)state.history.push(state.selected);state.selected=item;state.dependencies=[];state.external=[];state.reverse=[];state.reverseMeta=null;state.forwardNote='';state.tab='dependencies';state.busy=true;renderInventory();renderDetail();try{await resolveGraph(item);}catch(e){state.forwardNote=`Error al analizar relaciones: ${e.message||e}`;}finally{state.busy=false;renderDetail();}}
 async function scanReverse(){if(!state.selected||state.busy)return;const token=++state.reverseToken;state.busy=true;state.tab='usedby';renderDetail();try{const r=await state.portal.queryItems({query:portalQuery().replace(/\s+AND\s+type:"[^"]+"/g,''),start:1,num:app.config.reverseScanLimit,sortField:'modified',sortOrder:'desc'});const candidates=(r.results||r.items||[]).filter(x=>x.id!==state.selected.id);let checked=0;const matches=[];for(let i=0;i<candidates.length;i+=5){if(token!==state.reverseToken)return;const rows=await Promise.all(candidates.slice(i,i+5).map(async x=>{const p=await getItem(x.id);if(!p.portalItem)return null;try{const refs=collectRefs(await p.portalItem.fetchData('json')||{});checked++;if(refs.ids.includes(state.selected.id))return p.meta;}catch(e){checked++;}return null;}));matches.push(...rows.filter(Boolean));}state.reverse=matches;state.reverseMeta={checked,candidateCount:candidates.length,total:r.total||candidates.length};}catch(e){state.reverseMeta={error:e.message||String(e)};}finally{state.busy=false;if(token===state.reverseToken)renderDetail();}}
 function renderDetail(){
  detail.replaceChildren();if(!state.selected){detail.append(small('Selecciona un elemento del inventario para ver sus metadatos, dependencias y posibles consumidores.'));return;}
  const it=state.selected,header=cardBox();header.style.borderLeft=`4px solid ${C.blue}`;header.style.padding='15px';header.style.background='#f5f9fd';
  const title=el('div',it.title||'(Sin título)',{...wrap,display:'block',width:'100%',fontSize:'18px',fontWeight:'800',lineHeight:'1.4'});title.dataset.selectedTitle='true';header.append(title);
  header.append(el('div',it.type||'Tipo desconocido',{...wrap,color:C.blue,fontSize:'11px',fontWeight:'700',marginTop:'9px'}),small(`Propietario · ${it.owner||'No disponible'}`));
  const actions=el('div',null,{display:'block',width:'100%',marginTop:'12px',...wrap});const open=linkTo(it,'Abrir en ArcGIS ↗');if(open){open.dataset.openItem='true';Object.assign(open.style,{margin:'0',padding:'7px 10px',border:`1px solid ${C.line}`,borderRadius:'7px',background:'white',textDecoration:'none'});actions.append(open);}header.append(actions);
  const tabs=el('div',null,{display:'flex',flexWrap:'wrap',gap:'7px',paddingTop:'12px',marginTop:'12px',borderTop:`1px solid ${C.line}`});tabs.append(button(`UTILIZA · ${state.dependencies.length+state.external.length}`,()=>{state.tab='dependencies';renderDetail();},state.tab!=='dependencies'),button(`UTILIZADO POR · ${state.reverseMeta?state.reverse.length:'—'}`,scanReverse,state.tab!=='usedby'));if(state.history.length)tabs.append(button('← Elemento anterior',()=>selectItem(state.history.pop(),false),true));header.append(tabs);detail.append(header);
  if(state.busy)detail.append(small('Analizando relaciones…'));
  if(state.tab==='dependencies'){
   const count=state.dependencies.length+state.external.length;detail.append(section('Dependencias directas',count),small('Elementos y servicios referenciados por el elemento seleccionado.'));
   if(!count&&!state.busy)detail.append(small('No se han detectado dependencias en los datos accesibles. Esto no demuestra que no existan: puede haber fuentes en recursos o configuraciones no accesibles.'));
   for(const dep of state.dependencies){const node=itemCard(dep,d=>{if(!d.unresolved)selectItem(d);},{tone:dep.unresolved?C.amber:C.blue,badge:dep.unresolved?'REFERENCIA DE ÍTEM · NO RESUELTA':'ELEMENTO DE PORTAL · NAVEGAR PARA EXPLORAR'});const a=linkTo(dep,'Abrir ↗');if(a)node.append(a);detail.append(node);}
   if(state.external.length)detail.append(section('Servicios y recursos externos',state.external.length));for(const ext of state.external){const node=cardBox();node.style.borderLeft=`3px solid ${C.amber}`;node.append(small(ext.type));const a=el('a',ext.url,{color:C.blue,...wrap});a.href=ext.url;a.target='_blank';a.rel='noopener noreferrer';node.append(a,small(`Host · ${ext.owner}`));detail.append(node);}detail.append(small(state.forwardNote));
  }else{
   detail.append(section('Utilizado por · posible impacto',state.reverseMeta?state.reverse.length:null));if(state.reverseMeta?.error)detail.append(small(`No se pudo completar el análisis: ${state.reverseMeta.error}`));else if(state.reverseMeta)detail.append(small(`Coincidencias: ${state.reverse.length} · revisados: ${state.reverseMeta.checked} de ${state.reverseMeta.candidateCount}; el índice contiene ${state.reverseMeta.total} elementos. Cobertura parcial, no exhaustiva.`));else detail.append(small('El escaneo revisa hasta 60 elementos recientes accesibles; no representa necesariamente toda la organización.'));
   for(const dep of state.reverse){const node=itemCard(dep,selectItem,{tone:C.green,badge:'UTILIZA EL ELEMENTO SELECCIONADO'});const a=linkTo(dep,'Abrir ↗');if(a)node.append(a);detail.append(node);}if(state.reverseMeta&&!state.reverse.length&&!state.busy)detail.append(small('No se encontraron referencias entre los elementos escaneados. Como la cobertura es limitada, pueden existir otros consumidores.'));
  }
 }
 const verify=app.actions.register('verify-item-title',async({title})=>{const item=state.results.find(x=>x.title===title);if(!item)return{found:false};await selectItem(item);const t=detail.querySelector('[data-selected-title]'),a=detail.querySelector('[data-open-item]');const tr=t.getBoundingClientRect(),ar=a.getBoundingClientRect();return{found:true,title:t.textContent,titleWidth:tr.width,titleHeight:tr.height,linkBelowTitle:ar.top>=tr.bottom,titleOverflows:t.scrollWidth>t.clientWidth+1,headerOverflows:t.parentElement.scrollWidth>t.parentElement.clientWidth+1};});
 app.onCleanup(()=>{state.reverseToken++;verify.remove();inventory.replaceChildren();detail.replaceChildren();});
 renderDetail();try{const Portal=await app.import('esri/portal/Portal');state.portal=new Portal({url:app.portalUrl});await state.portal.load();state.username=state.portal.user?.username||'';state.orgId=state.portal.user?.orgId||state.portal.id||null;await runSearch(true);}catch(e){status.textContent=`Conexión no disponible: ${e.message||e}`;}
}